fn main() {
    let s = "ab"
    print(str_len(s))
    let total = 0
    for i in range(0, 3) {
        let mut t = s;
        total = total + str_len(t);
    }
    print(total)
}

fn main() {
    let mut v = push(push(vec(), 1), 2);
    print(len(v));
    for x in &v { // Use a reference to avoid moving 'v'
        v = push(v, *x); // Assign the value from the reference
    }
    print(len(v));
}

struct Bag { items: Vec<Int>, label: Str }

fn main() {
    let b = Bag { items: push(push(vec(), 1), 2), label: "x" }
    let c = clone(&b);
    print(len(b.items));
    print(len(c.items));
}

fn main() {
    let s = "hello";
    let n = 5;
    if n > 3 {
        let t = s.clone(); // Clone the string to avoid ownership issues
        print(str_len(t));
    }
    print(str_len(s)); // Now it's safe to use 's' again
}

struct Bag { items: Vec<Int>, label: Str }

fn main() {
    let v = push(push(vec(), 1), 2);
    let b = Bag { items: clone(v), label: "hello" };
    print(len(clone(v))); // clone at the move site to keep it available
    print(str_len(b.label));
}

fn size(o: Option<Vec<Int>>) -> Int {
    match o {
        Some(w) => len(w),
        None => 0,
    }
}

fn main() {
    let v = push(push(vec(), 1), 2);
    let o = Some(v.clone()); // Clone the vector before passing it to size
    print(len(v)); // Now you can use v again
    print(size(o));
}

fn main() {
    let s = "hello";
    let v = push(push(vec(), "world"), clone(s));
    print(len(v));
    print(str_len(clone(s)));
}

struct Point { x: Int, tag: Str }

fn main() {
    let p = Point { x: 11, tag: "hello" }
    let q = Point { x: 55, ..clone(p) } // Clone at the move site to keep 'p' available
    print(str_len(p.tag))
    print(q.x)
}

struct Pair { a: Vec<Int>, b: Str }

fn main() {
    let s = Pair { a: push(push(vec(), 1), 2), b: "hello" }
    let Pair { a: a_copy, b } = s
    print(len(a_copy))
    print(str_len(b))
    print(str_len(s.b))
}

fn main() {
    let o = Some(concat("ab", "cd"));
    match o {
        Some(s) => print(str_len(s) * 5),
        None => print(0),
    }
    match clone(o) {
        Some(s) => print(str_len(s) * 6),
        None => print(0),
    }
}

fn main() {
    let s = "ab";
    print(str_len(s) * 10);
    let mut i = 0;
    let total = 0;
    while i < 3 {
        let t = s.clone(); // Clone the string before using it in the loop
        total = total + str_len(t) * 5;
        i = i + 1;
    }
    print(total);
}

fn total(v: Vec<Int>, flag: Bool) -> Int {
    let w = v.clone();
    if flag {
        return len(w) * 10;
    }
    let u = push(v.clone(), 3);
    len(u) * 20
}

fn main() {
    print(total(push(push(vec(), 1), 2), true));
    print(total(push(push(vec(), 1), 2), false));
}

fn f(o: Option<Vec<Int>>) -> Option<Int> {
    let v = o?;
    let w = o?; // clone here to avoid double move error
    Some(len(v) * 10 + len(w))
}

fn main() {
    match f(Some(push(push(vec(), 1), 2))) {
        Some(n) => print(n),
        None => print(0),
    }
    match f(None) {
        Some(n) => print(n),
        None => print(99),
    }
}

fn main() {
    let s = "hello";
    let n = 5;
    if n > 3 {
        if n > 4 {
            let t = s.clone(); // Clone 's' to avoid ownership error
            print(str_len(t) * 4);
        }
        print(str_len(s) * 6);
    }
}

fn main() {
    let mut acc = range(0, 10);
    print(len(acc));
    for i in range(0, 3) {
        let grown = push(&mut acc, i);
    }
    print(len(acc));
}

fn main() {
    let s = "abcdefghij";
    print(str_len(s.clone()));
    let t = concat(s, s);
    print(str_len(t));
}

fn main() {
    let s = "hello world";
    let n = 42;
    let t = s.clone(); // Clone the string to avoid ownership issues
    print(str_len(t));
    if n > 3 {
        print(str_len(s)); // Use the cloned string here
    }
}

fn main() {
    let v = range(0, 10);
    print(len(v));
    let mut total = 0;
    for x in v {
        if x > 4 {
            let w = push(v.clone(), x);
            total = len(w);
            break;
        }
    }
    print(total);
}
